import React from 'react';
import { PieChart, Pie, Cell, ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Legend } from 'recharts';
import { Vulnerability, Severity } from '../types';
import { AlertTriangle, CheckCircle, Shield, Activity } from 'lucide-react';

interface DashboardProps {
  vulnerabilities: Vulnerability[];
}

const Dashboard: React.FC<DashboardProps> = ({ vulnerabilities }) => {
  const severityCounts = {
    [Severity.CRITICAL]: 0,
    [Severity.HIGH]: 0,
    [Severity.MEDIUM]: 0,
    [Severity.LOW]: 0,
    [Severity.INFO]: 0,
  };

  vulnerabilities.forEach(v => {
    if (severityCounts[v.severity] !== undefined) {
      severityCounts[v.severity]++;
    }
  });

  const pieData = Object.entries(severityCounts)
    .filter(([_, count]) => count > 0)
    .map(([name, value]) => ({ name, value }));

  const COLORS = {
    [Severity.CRITICAL]: '#ff4d4d',
    [Severity.HIGH]: '#ffbb00',
    [Severity.MEDIUM]: '#00ff9d', // Using accent for medium in this cyber theme usually implies "okay but watch out" or standard cyber color. Actually let's use orange for high, yellow for medium.
    [Severity.LOW]: '#3b82f6',
    [Severity.INFO]: '#9ca3af'
  };

  // Correction for standard semantic colors
  const SEMANTIC_COLORS = {
     [Severity.CRITICAL]: '#ef4444', // Red
     [Severity.HIGH]: '#f97316', // Orange
     [Severity.MEDIUM]: '#eab308', // Yellow
     [Severity.LOW]: '#3b82f6', // Blue
     [Severity.INFO]: '#94a3b8', // Slate
  };

  const StatCard = ({ title, value, icon, color }: any) => (
    <div className="bg-cyber-800 border border-cyber-700 p-6 rounded-lg shadow-lg relative overflow-hidden group">
      <div className={`absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-20 transition-opacity text-${color}-500`}>
        {icon}
      </div>
      <p className="text-gray-400 text-sm font-mono uppercase tracking-wider">{title}</p>
      <h3 className="text-3xl font-bold text-white mt-1">{value}</h3>
      <div className={`h-1 w-full mt-4 bg-gray-700 rounded-full overflow-hidden`}>
        <div className={`h-full bg-${color}-500`} style={{ width: '70%' }}></div>
      </div>
    </div>
  );

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <StatCard 
          title="Total Issues" 
          value={vulnerabilities.length} 
          icon={<AlertTriangle size={64} />} 
          color="cyber-accent" 
        />
        <StatCard 
          title="Critical Threats" 
          value={severityCounts[Severity.CRITICAL]} 
          icon={<Shield size={64} />} 
          color="red" 
        />
        <StatCard 
          title="High Severity" 
          value={severityCounts[Severity.HIGH]} 
          icon={<Activity size={64} />} 
          color="orange" 
        />
        <StatCard 
          title="Resolved" 
          value={0} 
          icon={<CheckCircle size={64} />} 
          color="blue" 
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-cyber-800 border border-cyber-700 p-6 rounded-lg">
          <h3 className="text-lg font-bold text-white mb-4 flex items-center">
            <Activity className="w-5 h-5 mr-2 text-cyber-accent" />
            Severity Distribution
          </h3>
          <div className="h-64">
            {pieData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={pieData}
                    cx="50%"
                    cy="50%"
                    innerRadius={60}
                    outerRadius={80}
                    paddingAngle={5}
                    dataKey="value"
                  >
                    {pieData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={SEMANTIC_COLORS[entry.name as Severity]} />
                    ))}
                  </Pie>
                  <Tooltip 
                    contentStyle={{ backgroundColor: '#111827', borderColor: '#374151', color: '#fff' }}
                  />
                  <Legend />
                </PieChart>
              </ResponsiveContainer>
            ) : (
              <div className="h-full flex items-center justify-center text-gray-500 font-mono">
                No data available. Start a scan.
              </div>
            )}
          </div>
        </div>

        <div className="bg-cyber-800 border border-cyber-700 p-6 rounded-lg">
          <h3 className="text-lg font-bold text-white mb-4 flex items-center">
            <Shield className="w-5 h-5 mr-2 text-cyber-accent" />
            Vulnerability List
          </h3>
          <div className="h-64 overflow-y-auto pr-2 space-y-3 custom-scrollbar">
            {vulnerabilities.length > 0 ? (
              vulnerabilities.map((vuln) => (
                <div key={vuln.id} className="bg-cyber-900 p-3 rounded border-l-4 border-l-red-500 border border-cyber-700">
                  <div className="flex justify-between items-start">
                    <span className="text-sm font-bold text-white">{vuln.title}</span>
                    <span className={`text-xs px-2 py-0.5 rounded ${
                        vuln.severity === Severity.CRITICAL ? 'bg-red-900 text-red-200' :
                        vuln.severity === Severity.HIGH ? 'bg-orange-900 text-orange-200' :
                        'bg-blue-900 text-blue-200'
                    }`}>
                      {vuln.severity}
                    </span>
                  </div>
                  <p className="text-xs text-gray-400 mt-1 truncate">{vuln.description}</p>
                </div>
              ))
            ) : (
               <div className="h-full flex items-center justify-center text-gray-500 font-mono">
                System clean or waiting for input.
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { gatherRepoIntelligence } from '../services/geminiService';
import { RepoIntelligence } from '../types';
import { Search, Globe, AlertOctagon, ExternalLink, Loader2 } from 'lucide-react';

interface RepoScannerProps {
  initialUrl?: string;
}

const RepoScanner: React.FC<RepoScannerProps> = ({ initialUrl = "https://github.com/picc-ai/nabis-notion-sync" }) => {
  const [url, setUrl] = useState(initialUrl);
  const [loading, setLoading] = useState(false);
  const [data, setData] = useState<RepoIntelligence | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleScan = async () => {
    if (!url) return;
    setLoading(true);
    setError(null);
    try {
      const result = await gatherRepoIntelligence(url);
      setData(result);
    } catch (e) {
      setError("Failed to gather intelligence. Verify API Key and network connection.");
    } finally {
      setLoading(false);
    }
  };

  // Auto-scan if initial URL provided? Maybe better to let user click to save tokens.
  // Let's just default input.

  return (
    <div className="space-y-6 max-w-4xl mx-auto">
      <div className="bg-cyber-800 p-8 rounded-xl border border-cyber-700 shadow-2xl">
        <div className="text-center mb-8">
          <h2 className="text-2xl font-bold text-white mb-2">Repository Intelligence</h2>
          <p className="text-gray-400">Scan public repositories for known vulnerabilities, tech stack risks, and community issues.</p>
        </div>

        <div className="flex gap-4 mb-6">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-3 text-gray-500" size={20} />
            <input
              type="text"
              value={url}
              onChange={(e) => setUrl(e.target.value)}
              placeholder="https://github.com/username/repo"
              className="w-full bg-cyber-900 border border-cyber-700 text-white pl-10 pr-4 py-3 rounded-lg focus:outline-none focus:border-cyber-accent transition-colors font-mono"
            />
          </div>
          <button
            onClick={handleScan}
            disabled={loading}
            className="bg-cyber-accent hover:bg-emerald-400 text-cyber-900 font-bold py-3 px-6 rounded-lg transition-colors flex items-center disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {loading ? <Loader2 className="animate-spin mr-2" /> : <Globe className="mr-2" />}
            {loading ? 'SCANNING...' : 'INITIATE SCAN'}
          </button>
        </div>

        {error && (
          <div className="bg-red-900/20 border border-red-800 text-red-400 p-4 rounded-lg mb-6 flex items-center">
            <AlertOctagon className="mr-3" />
            {error}
          </div>
        )}

        {data && (
          <div className="space-y-6 animate-fade-in">
            <div className="bg-cyber-900/50 p-6 rounded-lg border border-cyber-700">
              <h3 className="text-lg font-bold text-cyber-accent mb-3 uppercase tracking-wider">Executive Summary</h3>
              <p className="text-gray-300 leading-relaxed">{data.summary}</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="bg-cyber-900/50 p-6 rounded-lg border border-cyber-700">
                <h3 className="text-lg font-bold text-orange-400 mb-3 uppercase tracking-wider flex items-center">
                  <AlertOctagon className="mr-2 w-5 h-5" />
                  Tech Stack Risks
                </h3>
                <ul className="space-y-2">
                  {data.techStackRisks.map((risk, idx) => (
                    <li key={idx} className="flex items-start text-sm text-gray-300">
                      <span className="text-orange-500 mr-2">•</span>
                      {risk}
                    </li>
                  ))}
                </ul>
              </div>

              <div className="bg-cyber-900/50 p-6 rounded-lg border border-cyber-700">
                <h3 className="text-lg font-bold text-blue-400 mb-3 uppercase tracking-wider flex items-center">
                  <Globe className="mr-2 w-5 h-5" />
                  Recent Intel
                </h3>
                <ul className="space-y-2">
                  {data.recentIssues.map((issue, idx) => (
                    <li key={idx} className="flex items-start text-sm text-gray-300">
                      <span className="text-blue-500 mr-2">•</span>
                      {issue}
                    </li>
                  ))}
