export default RepoScanner;

import React, { useState } from 'react';
import { analyzeCodeBlock } from '../services/geminiService';
import { Vulnerability, Severity } from '../types';
import { FileCode, Play, AlertTriangle, Bug, Lightbulb, Trash2 } from 'lucide-react';

interface CodeAnalyzerProps {
  onResultsFound: (vulns: Vulnerability[]) => void;
}

const CodeAnalyzer: React.FC<CodeAnalyzerProps> = ({ onResultsFound }) => {
  const [code, setCode] = useState('');
  const [filename, setFilename] = useState('unknown.ts');
  const [loading, setLoading] = useState(false);
  const [localVulns, setLocalVulns] = useState<Vulnerability[]>([]);

  const handleAnalyze = async () => {
    if (!code.trim()) return;
    setLoading(true);
    setLocalVulns([]);

    try {
      const results = await analyzeCodeBlock(code, filename);
      setLocalVulns(results);
      onResultsFound(results);
    } catch (e) {
      console.error(e);
      alert("Analysis failed. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const clear = () => {
    setCode('');
    setLocalVulns([]);
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 h-full">
      <div className="flex flex-col h-full bg-cyber-800 rounded-lg border border-cyber-700 overflow-hidden">
        <div className="bg-cyber-900 p-3 border-b border-cyber-700 flex justify-between items-center">
          <div className="flex items-center space-x-2">
            <FileCode className="text-cyber-accent w-5 h-5" />
            <input 
              type="text" 
              value={filename}
              onChange={(e) => setFilename(e.target.value)}
              className="bg-transparent text-sm font-mono text-white focus:outline-none border-b border-dashed border-gray-600 focus:border-cyber-accent w-48"
              placeholder="filename.ts"
            />
          </div>
          <div className="flex space-x-2">
             <button onClick={clear} className="p-1 hover:bg-red-900/30 text-gray-400 hover:text-red-400 rounded">
              <Trash2 size={16} />
            </button>
          </div>
        </div>
        <textarea
          value={code}
          onChange={(e) => setCode(e.target.value)}
          placeholder="// Paste source code here for deep security analysis..."
          className="flex-1 bg-cyber-900/50 p-4 font-mono text-sm text-gray-300 resize-none focus:outline-none custom-scrollbar"
          spellCheck={false}
        />
        <div className="p-4 border-t border-cyber-700 bg-cyber-800">
          <button
            onClick={handleAnalyze}
            disabled={loading || !code.trim()}
            className="w-full bg-cyber-accent hover:bg-emerald-400 text-cyber-900 font-bold py-3 rounded transition-all flex justify-center items-center disabled:opacity-50"
          >
            {loading ? (
              <span className="flex items-center">
                <span className="w-2 h-2 bg-cyber-900 rounded-full animate-bounce mr-1"></span>
                <span className="w-2 h-2 bg-cyber-900 rounded-full animate-bounce mr-1 delay-100"></span>
                <span className="w-2 h-2 bg-cyber-900 rounded-full animate-bounce delay-200"></span>
              </span>
            ) : (
              <>
                <Play size={18} className="mr-2 fill-current" /> ANALYZE CODE BLOCK
              </>
            )}
          </button>
        </div>
      </div>

      <div className="flex flex-col h-full bg-cyber-800 rounded-lg border border-cyber-700 overflow-hidden">
        <div className="bg-cyber-900 p-3 border-b border-cyber-700">
          <h3 className="text-sm font-bold text-white uppercase tracking-wider flex items-center">
            <Bug className="w-4 h-4 mr-2 text-red-500" />
            Analysis Results
          </h3>
        </div>
        <div className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar">
          {localVulns.length === 0 && !loading && (
            <div className="h-full flex flex-col items-center justify-center text-gray-600 opacity-50">
              <FileCode size={48} className="mb-4" />
              <p className="text-sm">Awaiting code input...</p>
            </div>
          )}

          {loading && (
             <div className="space-y-4">
               {[1,2,3].map(i => (
                 <div key={i} className="animate-pulse bg-cyber-900 p-4 rounded border border-cyber-700 h-24"></div>
               ))}
             </div>
          )}

          {localVulns.map((vuln) => (
            <div key={vuln.id} className="bg-cyber-900 rounded border-l-4 border border-cyber-700 p-4 relative group hover:border-cyber-accent transition-colors" 
              style={{ borderLeftColor: vuln.severity === Severity.CRITICAL ? '#ef4444' : vuln.severity === Severity.HIGH ? '#f97316' : '#eab308' }}
            >
              <div className="flex justify-between items-start mb-2">
                <h4 className="font-bold text-white">{vuln.title}</h4>
                <span className={`text-[10px] uppercase font-bold px-2 py-0.5 rounded text-white
                   ${vuln.severity === Severity.CRITICAL ? 'bg-red-600' : vuln.severity === Severity.HIGH ? 'bg-orange-600' : 'bg-yellow-600'}
                `}>
                  {vuln.severity}
                </span>
              </div>
              <p className="text-sm text-gray-400 mb-3">{vuln.description}</p>

              <div className="flex items-start bg-cyber-800 p-2 rounded text-xs text-green-400 font-mono">
                <Lightbulb size={14} className="mr-2 mt-0.5 flex-shrink-0" />
                {vuln.suggestion}
              </div>

              {vuln.line && (
                <div className="absolute top-4 right-12 text-xs font-mono text-gray-600">
                  Line: {vuln.line}
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default CodeAnalyzer;

import React from 'react';
import { Vulnerability } from '../types';
import { FileText, Download } from 'lucide-react';

interface ReportsProps {
  vulnerabilities: Vulnerability[];
}

const Reports: React.FC<ReportsProps> = ({ vulnerabilities }) => {

  const generateMarkdown = () => {
    const header = `# Security Assessment Report\nGenerated by SecurIntell AI\nDate: ${new Date().toLocaleDateString()}\n\n`;
    const summary = `## Summary\nTotal Issues Found: ${vulnerabilities.length}\n\n`;
    const content = vulnerabilities.map(v => 
      `### ${v.title} (${v.severity})\n**File:** ${v.file || 'N/A'}\n**Description:** ${v.description}\n**Recommendation:** ${v.suggestion}\n`
    ).join('\n---\n\n');

    return header + summary + content;
  };

  const downloadReport = () => {
    const element = document.createElement("a");
    const file = new Blob([generateMarkdown()], {type: 'text/markdown'});
    element.href = URL.createObjectURL(file);
    element.download = "security_report.md";
    document.body.appendChild(element); // Required for this to work in FireFox
    element.click();
  };

  return (
    <div className="max-w-4xl mx-auto space-y-6">
       <div className="bg-cyber-800 p-8 rounded-xl border border-cyber-700 flex justify-between items-center">
         <div>
            <h2 className="text-2xl font-bold text-white">Security Report Generation</h2>
            <p className="text-gray-400 text-sm mt-1">Export current session findings to Markdown.</p>
         </div>
         <button onClick={downloadReport} className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-3 rounded-lg font-bold flex items-center transition-colors">
            <Download className="mr-2" /> Export Report
         </button>
       </div>

       <div className="bg-cyber-900 p-6 rounded-lg border border-cyber-700 font-mono text-sm text-gray-300 whitespace-pre-wrap">
          {vulnerabilities.length > 0 ? generateMarkdown() : "No vulnerabilities recorded in this session. Run an analysis to generate a report."}
       </div>
    </div>
  );
};

export default Reports;

