import { GoogleGenAI, Type } from "@google/genai";
import { Vulnerability, Severity, RepoIntelligence, ScanResult, SystemArchitecture } from '../types';

const getAiClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key not found in environment variables");
  }
  return new GoogleGenAI({ apiKey });
};

export const analyzeCodeBlock = async (code: string, filename: string): Promise<Vulnerability[]> => {
  const ai = getAiClient();

  const prompt = `
    Analyze the following code snippet (Filename: ${filename}) for security vulnerabilities, logic bugs, and code quality issues.
    Focus on OWASP Top 10, potential memory leaks, unhandled exceptions, and bad practices.

    Code:
    \`\`\`
    ${code}
    \`\`\`
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 2048 }, // Allow some thinking for deep analysis
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              description: { type: Type.STRING },
              severity: { type: Type.STRING, enum: ["Critical", "High", "Medium", "Low", "Info"] },
              line: { type: Type.INTEGER },
              suggestion: { type: Type.STRING },
              cwe: { type: Type.STRING }
            },
            required: ["title", "description", "severity", "suggestion"]
          }
        }
      }
    });

    const text = response.text;
    if (!text) return [];

    const rawData = JSON.parse(text);
    // Add IDs and filename
    return rawData.map((v: any, index: number) => ({
      ...v,
      id: `vuln-${Date.now()}-${index}`,
      file: filename
    }));

  } catch (error) {
    console.error("Analysis failed:", error);
    throw error;
  }
};

export const gatherRepoIntelligence = async (repoUrl: string): Promise<RepoIntelligence> => {
  const ai = getAiClient();

  const prompt = `
    Conduct a security intelligence gathering operation on the following public GitHub repository: ${repoUrl}.

    1. Identify the primary technology stack and its common associated security risks (e.g., Notion API keys, sync logic loops, Python dependencies).
    2. Search for any public discussions, known issues, or "post-mortems" related to this specific repo or similar "Notion Sync" tools.
    3. Summarize the overall security posture based on public information.

    If the repo is small or unknown, generalize based on the name and implied functionality (Notion Sync).
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            summary: { type: Type.STRING },
            techStackRisks: { 
              type: Type.ARRAY,
              items: { type: Type.STRING }
            },
            recentIssues: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          }
        }
      }
    });

    const text = response.text;
    const data = JSON.parse(text || "{}");

    // Extract grounding chunks for sources
    const sources = response.candidates?.[0]?.groundingMetadata?.groundingChunks
      ?.map((chunk: any) => {
        if (chunk.web) return { title: chunk.web.title, uri: chunk.web.uri };
        return null;
      })
      .filter((s: any) => s !== null) || [];

    return {
      summary: data.summary || "No summary available.",
      techStackRisks: data.techStackRisks || [],
      recentIssues: data.recentIssues || [],
      sources: sources as any
    };

  } catch (error) {
    console.error("Intelligence gathering failed:", error);
    throw error;
  }
};

export const analyzeSystemArchitecture = async (repoUrl: string): Promise<SystemArchitecture> => {
  const ai = getAiClient();

  const prompt = `
    You are a Security Architect. Analyze the repository at ${repoUrl} (or infer from name 'nabis-notion-sync' if inaccessible).

    TASK 1: Repository Explanation
    Provide a clear, high-level overview of what this application does, its architecture, and data flow.

    TASK 2: Agent Role Identification
    Identify all "Agents" involved in this system. This includes:
    - Internal Software Components (e.g., 'SyncManager', 'NotionClient', 'DatabaseWorker').
    - External Services (e.g., 'Notion API', 'Database Provider').
    - REQUIRED: Include "Security Agents" for CI/CD as separate roles (e.g., 'OWASP Dependency-Check', 'Snyk Bot', 'Trivy Scanner', 'SonarQube Auditor').

    TASK 3: Generate Security Pipelines
    Generate valid GitHub Actions YAML content for a continuous integration pipeline that implements:
    - OWASP Dependency-Check
    - Snyk Vulnerability Scanner
    - Trivy Container/FS Scanner
    - SonarQube SAST analysis
    - Dependency auditing (npm audit/pip-audit)

    Return a strictly structured JSON response.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 4096 },
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            overview: { type: Type.STRING },
            agents: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  type: { type: Type.STRING, enum: ['Internal Component', 'Security Bot', 'External Service'] },
                  description: { type: Type.STRING },
                  responsibilities: { type: Type.ARRAY, items: { type: Type.STRING } }
                }
              }
            },
            pipelines: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  description: { type: Type.STRING },
                  yaml: { type: Type.STRING }
                }
              }
            }
          }
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No data returned from AI");

    return JSON.parse(text) as SystemArchitecture;

  } catch (error) {
    console.error("Architecture analysis failed:", error);
    throw error;
  }
};

import React, { useState } from 'react';
import { analyzeSystemArchitecture } from '../services/geminiService';
import { SystemArchitecture } from '../types';
import { Network, Bot, Server, Shield, Play, Copy, Check, Loader2, GitBranch, Terminal } from 'lucide-react';

interface ArchitectureViewProps {
  initialUrl?: string;
}

const ArchitectureView: React.FC<ArchitectureViewProps> = ({ initialUrl = "https://github.com/picc-ai/nabis-notion-sync" }) => {
  const [url, setUrl] = useState(initialUrl);
  const [loading, setLoading] = useState(false);
  const [data, setData] = useState<SystemArchitecture | null>(null);
  const [copiedIndex, setCopiedIndex] = useState<number | null>(null);

  const handleAnalyze = async () => {
    setLoading(true);
    try {
      const result = await analyzeSystemArchitecture(url);
      setData(result);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const copyToClipboard = (text: string, index: number) => {
    navigator.clipboard.writeText(text);
    setCopiedIndex(index);
    setTimeout(() => setCopiedIndex(null), 2000);
  };

  return (
    <div className="space-y-8 max-w-6xl mx-auto pb-12">
      <div className="bg-cyber-800 p-8 rounded-xl border border-cyber-700 shadow-2xl">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-8 gap-4">
          <div>
            <h2 className="text-2xl font-bold text-white flex items-center">
              <Network className="mr-3 text-cyber-accent" />
              System Architecture & Agent Roles
            </h2>
            <p className="text-gray-400 mt-1">Analyze repository purpose, identify actors, and generate security pipelines.</p>
          </div>
          <div className="flex w-full md:w-auto gap-2">
            <input 
              type="text" 
              value={url}
              onChange={(e) => setUrl(e.target.value)}
              className="bg-cyber-900 border border-cyber-700 text-sm rounded px-3 py-2 text-white w-full md:w-64 font-mono focus:border-cyber-accent focus:outline-none"
            />
            <button 
              onClick={handleAnalyze}
              disabled={loading}
              className="bg-cyber-accent hover:bg-emerald-400 text-cyber-900 font-bold px-4 py-2 rounded flex items-center transition-colors disabled:opacity-50 whitespace-nowrap"
            >
              {loading ? <Loader2 className="animate-spin mr-2" size={18} /> : <Play className="mr-2" size={18} />}
              ANALYZE
            </button>
          </div>
        </div>

        {!data && !loading && (
          <div className="text-center py-20 border-2 border-dashed border-cyber-700 rounded-lg">
            <Network className="mx-auto h-12 w-12 text-gray-600 mb-4" />
            <p className="text-gray-500">Initiate analysis to map system architecture and agents.</p>
          </div>
        )}

        {loading && (
          <div className="space-y-4 animate-pulse">
            <div className="h-40 bg-cyber-900 rounded-lg"></div>
            <div className="grid grid-cols-3 gap-4">
              <div className="h-32 bg-cyber-900 rounded-lg"></div>
              <div className="h-32 bg-cyber-900 rounded-lg"></div>
              <div className="h-32 bg-cyber-900 rounded-lg"></div>
            </div>
          </div>
        )}

        {data && (
          <div className="space-y-8 animate-fade-in">
            {/* Overview Section */}
            <section className="bg-cyber-900/50 p-6 rounded-lg border border-cyber-700">
              <h3 className="text-lg font-bold text-white mb-4 uppercase tracking-wider border-b border-cyber-700 pb-2">Repository Overview</h3>
              <p className="text-gray-300 leading-relaxed whitespace-pre-line">{data.overview}</p>
            </section>

            {/* Agents Grid */}
            <section>
              <h3 className="text-lg font-bold text-white mb-4 uppercase tracking-wider flex items-center">
                <Bot className="mr-2 text-blue-400" />
                Identified Agent Roles
              </h3>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {data.agents.map((agent, idx) => (
                  <div key={idx} className="bg-cyber-900 p-5 rounded-lg border border-cyber-700 hover:border-blue-500/50 transition-colors group">
                    <div className="flex items-center justify-between mb-3">
                      <div className="flex items-center space-x-2">
                        {agent.type === 'Security Bot' ? <Shield size={18} className="text-red-400" /> : 
                         agent.type === 'External Service' ? <Server size={18} className="text-purple-400" /> :
                         <Bot size={18} className="text-blue-400" />}
                        <span className="font-bold text-white text-sm">{agent.name}</span>
                      </div>
                      <span className={`text-[10px] uppercase px-2 py-0.5 rounded border ${
                        agent.type === 'Security Bot' ? 'border-red-900 text-red-300 bg-red-900/20' :
                        agent.type === 'External Service' ? 'border-purple-900 text-purple-300 bg-purple-900/20' :
                        'border-blue-900 text-blue-300 bg-blue-900/20'
                      }`}>{agent.type}</span>
                    </div>
                    <p className="text-xs text-gray-400 mb-3 h-10 overflow-hidden">{agent.description}</p>
                    <ul className="space-y-1">
                      {agent.responsibilities.slice(0, 3).map((resp, rIdx) => (
                        <li key={rIdx} className="text-[10px] text-gray-500 flex items-start">
                          <span className="mr-1.5 text-cyber-accent">•</span>{resp}
                        </li>
                      ))}
                    </ul>
                  </div>
                ))}
              </div>
            </section>

            {/* Generated Pipelines */}
            <section>
              <h3 className="text-lg font-bold text-white mb-4 uppercase tracking-wider flex items-center">
                <GitBranch className="mr-2 text-orange-400" />
                Generated Security Pipelines
              </h3>
              <div className="space-y-6">
                {data.pipelines.map((pipeline, idx) => (
                  <div key={idx} className="bg-cyber-900 rounded-lg border border-cyber-700 overflow-hidden">
                    <div className="bg-cyber-900 p-4 border-b border-cyber-700 flex justify-between items-center">
                      <div>
                        <h4 className="font-bold text-white text-sm flex items-center">
                          <Terminal className="w-4 h-4 mr-2 text-gray-400" />
                          {pipeline.name}
                        </h4>
                        <p className="text-xs text-gray-500 mt-0.5">{pipeline.description}</p>
                      </div>
                      <button 
                        onClick={() => copyToClipboard(pipeline.yaml, idx)}
                        className="text-xs flex items-center bg-cyber-800 hover:bg-cyber-700 text-gray-300 px-3 py-1.5 rounded transition-colors border border-cyber-700"
                      >
                        {copiedIndex === idx ? <Check size={14} className="mr-1.5 text-green-500" /> : <Copy size={14} className="mr-1.5" />}
                        {copiedIndex === idx ? 'COPIED' : 'COPY YAML'}
                      </button>
                    </div>
                    <div className="p-4 bg-[#0d1117] overflow-x-auto">
                      <pre className="font-mono text-xs text-gray-300 leading-relaxed">
                        <code>{pipeline.yaml}</code>
                      </pre>
                    </div>
                  </div>
                ))}
              </div>
            </section>
          </div>
        )}
      </div>
    </div>
  );
};

