const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<ViewState>('dashboard');
  const [vulnerabilities, setVulnerabilities] = useState<Vulnerability[]>([]);
  // In a real app, this would be global state or context
  const targetRepo = "https://github.com/picc-ai/nabis-notion-sync";

  const handleNewFindings = (newVulns: Vulnerability[]) => {
    setVulnerabilities(prev => [...newVulns, ...prev]);
  };

  const renderView = () => {
    switch(currentView) {
      case 'dashboard':
        return <Dashboard vulnerabilities={vulnerabilities} targetRepo={targetRepo} />;
      case 'scanner':
        return <RepoScanner initialUrl={targetRepo} />;
      case 'analyzer':
        return <CodeAnalyzer onResultsFound={handleNewFindings} />;
      case 'reports':
        return <Reports vulnerabilities={vulnerabilities} />;
      case 'architecture':
        return <ArchitectureView initialUrl={targetRepo} />;
      default:
        return <Dashboard vulnerabilities={vulnerabilities} targetRepo={targetRepo} />;
