import React, { useState } from 'react';
import { PieChart, Pie, Cell, ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Legend } from 'recharts';
import { Vulnerability, Severity } from '../types';
import { generateIssueDraft } from '../services/geminiService';
import { AlertTriangle, CheckCircle, Shield, Activity, Bug, ExternalLink, Loader2 } from 'lucide-react';

interface DashboardProps {
  vulnerabilities: Vulnerability[];
  targetRepo?: string;
}

const Dashboard: React.FC<DashboardProps> = ({ vulnerabilities, targetRepo = "https://github.com/picc-ai/nabis-notion-sync" }) => {
  const [generatingTicketId, setGeneratingTicketId] = useState<string | null>(null);

  const severityCounts = {
    [Severity.CRITICAL]: 0,
    [Severity.HIGH]: 0,
    [Severity.MEDIUM]: 0,
    [Severity.LOW]: 0,
    [Severity.INFO]: 0,
  };

  vulnerabilities.forEach(v => {
    if (severityCounts[v.severity] !== undefined) {
      severityCounts[v.severity]++;
    }
  });

  const pieData = Object.entries(severityCounts)
    .filter(([_, count]) => count > 0)
    .map(([name, value]) => ({ name, value }));

  const COLORS = {
    [Severity.CRITICAL]: '#ff4d4d',
    [Severity.HIGH]: '#ffbb00',
    [Severity.MEDIUM]: '#00ff9d',
    [Severity.LOW]: '#3b82f6',
    [Severity.INFO]: '#9ca3af'
  };

  const SEMANTIC_COLORS = {
     [Severity.CRITICAL]: '#ef4444', // Red
     [Severity.HIGH]: '#f97316', // Orange
     [Severity.MEDIUM]: '#eab308', // Yellow
     [Severity.LOW]: '#3b82f6', // Blue
     [Severity.INFO]: '#94a3b8', // Slate
  };

  const handleCreateTicket = async (vuln: Vulnerability) => {
    setGeneratingTicketId(vuln.id);
    try {
      const draft = await generateIssueDraft(vuln, targetRepo);
      // Construct GitHub new issue URL
      // Remove trailing .git if present and ensure slash at end for simpler concatenation logic or just simple parsing
      const cleanRepoUrl = targetRepo.replace('.git', '');
      const title = encodeURIComponent(draft.title);
      const body = encodeURIComponent(draft.body);
      const labels = encodeURIComponent(draft.labels.join(','));

      const url = `${cleanRepoUrl}/issues/new?title=${title}&body=${body}&labels=${labels}`;
      window.open(url, '_blank');
    } catch (e) {
      console.error("Failed to generate ticket", e);
