          color="blue" 
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-cyber-800 border border-cyber-700 p-6 rounded-lg">
          <h3 className="text-lg font-bold text-white mb-4 flex items-center">
